<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Background Remover — SmartToolz</title><meta name="description" content="Remove image backgrounds online for free with SmartToolz."><style>*{box-sizing:border-box}body{margin:0;background:#f6f8fc;color:#172033;font-family:Inter,system-ui,Arial,sans-serif}.page{width:min(1000px,calc(100% - 24px));margin:30px auto 60px}.card{background:#fff;border:1px solid #e5e9f0;border-radius:20px;padding:26px;box-shadow:0 14px 40px rgba(20,30,70,.05)}h1{margin:0 0 8px;font-size:clamp(30px,5vw,46px)}p{color:#707b8e}.drop{margin-top:20px;padding:50px 20px;border:2px dashed #d7dbea;border-radius:16px;text-align:center;background:#fafbff;cursor:pointer}.drop:hover{border-color:#635bff;background:#f5f3ff}#picker{display:none}.btn{display:inline-block;border:0;border-radius:10px;padding:11px 16px;background:#635bff;color:#fff;font-weight:800;cursor:pointer;margin-top:12px}.viewer{display:none;margin-top:20px;text-align:center}.viewer img{max-width:100%;max-height:600px}.status{margin-top:12px;font-size:13px;font-weight:700;color:#635bff}</style></head><body><main class="page"><section class="card"><h1>Background Remover</h1><p>Remove image backgrounds directly in your browser. No login, analytics or tracking.</p><div class="drop" id="drop">🖼️<br><strong>Choose or drop an image</strong><br><small>PNG, JPG or WebP</small><input id="picker" type="file" accept="image/png,image/jpeg,image/webp"></div><div class="viewer" id="viewer"><img id="preview" alt="Background removed result"><div class="status" id="status">Processing…</div><button class="btn" id="download" type="button">Download PNG</button></div></section></main><?php require_once dirname(__DIR__) . '/footer.php'; ?><script type="module">import{removeBackground}from'https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm';const drop=document.getElementById('drop'),picker=document.getElementById('picker'),viewer=document.getElementById('viewer'),preview=document.getElementById('preview'),status=document.getElementById('status'),download=document.getElementById('download');let url='';async function run(file){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))return alert('Please choose a PNG, JPG or WebP image.');drop.style.display='none';viewer.style.display='block';status.textContent='Removing background…';try{const blob=await removeBackground(file,{model:'isnet',device:'cpu',proxyToWorker:true,output:{format:'image/png',quality:1}});if(!blob||!blob.size)throw new Error('Empty result');if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(blob);preview.src=url;status.textContent='Background removed successfully.';download.onclick=()=>{const a=document.createElement('a');a.href=url;a.download='smarttoolz-background-removed.png';a.click()}}catch(e){console.error(e);status.textContent='Could not remove the background. Please try another image.'}}drop.onclick=()=>picker.click();picker.onchange=()=>run(picker.files?.[0]);drop.ondragover=e=>{e.preventDefault();drop.style.borderColor='#635bff'};drop.ondrop=e=>{e.preventDefault();run(e.dataTransfer.files?.[0])};window.addEventListener('beforeunload',()=>url&&URL.revokeObjectURL(url));</script></body></html>